    11  /*
    12  ** Main entry point.  The fuzzer invokes this function with each
    13  ** fuzzed input.
    14  */
    15  extern "C" int
    16  LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    17      UA_Connection c = createDummyConnection(65535, NULL);
    18      UA_ServerConfig *config = UA_ServerConfig_new_default();
    19      UA_Server *server = UA_Server_new(config);
    20      if (server == NULL) {
    21          UA_LOG_ERROR(UA_Log_Stdout, UA_LOGCATEGORY_SERVER,
    22                       "Could not create server instance using UA_Server_new");
    23          return 1;
    24      }
    25
    26      // we need to copy the message because it will be freed in the processing function
    27      UA_ByteString msg = UA_ByteString();
    28      UA_StatusCode retval = UA_ByteString_allocBuffer(&msg, size);
    29      if(retval != UA_STATUSCODE_GOOD)
    30          return (int)retval;
    31      memcpy(msg.data, data, size);
    32
    33      UA_Server_processBinaryMessage(server, &c, &msg);
    34      // if we got an invalid chunk, the message is not deleted, so delete it here
    35      UA_ByteString_deleteMembers(&msg);
    36      UA_Server_run_shutdown(server);
    37      UA_Server_delete(server);
    38      UA_ServerConfig_delete(config);
    39      c.close(&c);
    40      UA_Connection_deleteMembers(&c);
    41      return 0;
    42  }
