    19  void UA_WorkQueue_init(UA_WorkQueue *wq) {
    20      /* Initialized the linked list for delayed callbacks */
    21      SIMPLEQ_INIT(&wq->delayedCallbacks);
    22
    23  #ifdef UA_ENABLE_MULTITHREADING
    24      wq->delayedCallbacks_checkpoint = NULL;
    25      pthread_mutex_init(&wq->delayedCallbacks_accessMutex,  NULL);
    26
    27      /* Initialize the dispatch queue for worker threads */
    28      SIMPLEQ_INIT(&wq->dispatchQueue);
    29      pthread_mutex_init(&wq->dispatchQueue_accessMutex, NULL);
    30      pthread_cond_init(&wq->dispatchQueue_condition, NULL);
    31      pthread_mutex_init(&wq->dispatchQueue_conditionMutex, NULL);
    32  #endif
    33  }
