   116  /* Can be called repeatedly and starts additional workers */
   117  UA_StatusCode
   118  UA_WorkQueue_start(UA_WorkQueue *wq, size_t workersCount) {
   119      if(wq->workersSize > 0 || workersCount == 0)
   120          return UA_STATUSCODE_BADINTERNALERROR;
   121
   122      /* Create the worker array */
   123      wq->workers = (UA_Worker*)UA_calloc(workersCount, sizeof(UA_Worker));
   124      if(!wq->workers)
   125          return UA_STATUSCODE_BADOUTOFMEMORY;
   126      wq->workersSize = workersCount;
   127
   128      /* Spin up the workers */
   129      for(size_t i = 0; i < workersCount; ++i) {
   130          UA_Worker *w = &wq->workers[i];
   131          w->queue = wq;
   132          w->counter = 0;
   133          w->running = true;
   134          pthread_create(&w->thread, NULL, (void* (*)(void*))workerLoop, w);
   135      }
   136      return UA_STATUSCODE_GOOD;
   137  }
   138
   139  void UA_WorkQueue_stop(UA_WorkQueue *wq) {
   140      if(wq->workersSize == 0)
   141          return;
   142
   143      /* Signal the workers to stop */
   144      for(size_t i = 0; i < wq->workersSize; ++i)
   145          wq->workers[i].running = false;
   146
   147      /* Wake up all workers */
   148      pthread_cond_broadcast(&wq->dispatchQueue_condition);
   149
   150      /* Wait for the workers to finish, then clean up */
   151      for(size_t i = 0; i < wq->workersSize; ++i)
   152          pthread_join(wq->workers[i].thread, NULL);
   153
   154      UA_free(wq->workers);
   155      wq->workers = NULL;
   156      wq->workersSize = 0;
   157  }
