   159  void UA_WorkQueue_enqueue(UA_WorkQueue *wq, UA_ApplicationCallback cb,
   160                            void *application, void *data) {
   161      UA_DelayedCallback *dc = (UA_DelayedCallback*)UA_malloc(sizeof(UA_DelayedCallback));
   162      if(!dc) {
   163          cb(application, data); /* Execute immediately if the memory could not be allocated */
   164          return;
   165      }
   166
   167      dc->callback = cb;
   168      dc->application = application;
   169      dc->data = data;
   170
   171      /* Enqueue for the worker threads */
   172      pthread_mutex_lock(&wq->dispatchQueue_accessMutex);
   173      SIMPLEQ_INSERT_TAIL(&wq->dispatchQueue, dc, next);
   174      pthread_mutex_unlock(&wq->dispatchQueue_accessMutex);
   175
   176      /* Wake up sleeping workers */
   177      pthread_cond_broadcast(&wq->dispatchQueue_condition);
   178  }
