   182  /*********************/
   183  /* Delayed Callbacks */
   184  /*********************/
   185
   186  #ifdef UA_ENABLE_MULTITHREADING
   187
   188  /* Delayed Callbacks are called only when all callbacks that were dispatched
   189   * prior are finished. After every UA_MAX_DELAYED_SAMPLE delayed Callbacks that
   190   * were added to the queue, we sample the counters from the workers. The
   191   * counters are compared to the last counters that were sampled. If every worker
   192   * has proceeded the counter, then we know that all delayed callbacks prior to
   193   * the last sample-point are safe to execute. */
   194
   195  /* Sample the worker counter for every nth delayed callback. This is used to
   196   * test that all workers have **finished** their current job before the delayed
   197   * callback is processed. */
   198  #define UA_MAX_DELAYED_SAMPLE 100
   199
   200  /* Call only with a held mutex for the delayed callbacks */
   201  static void
   202  dispatchDelayedCallbacks(UA_WorkQueue *wq, UA_DelayedCallback *cb) {
   203      /* Are callbacks before the last checkpoint ready? */
   204      for(size_t i = 0; i < wq->workersSize; ++i) {
   205          if(wq->workers[i].counter == wq->workers[i].checkpointCounter)
   206              return;
   207      }
   208
   209      /* Dispatch all delayed callbacks up to the checkpoint.
   210       * TODO: Move over the entire queue up to the checkpoint in one step. */
   211      if(wq->delayedCallbacks_checkpoint != NULL) {
   212          UA_DelayedCallback *iter, *tmp_iter;
   213          SIMPLEQ_FOREACH_SAFE(iter, &wq->delayedCallbacks, next, tmp_iter) {
   214              pthread_mutex_lock(&wq->dispatchQueue_accessMutex);
   215              SIMPLEQ_INSERT_TAIL(&wq->dispatchQueue, iter, next);
   216              pthread_mutex_unlock(&wq->dispatchQueue_accessMutex);
   217              if(iter == wq->delayedCallbacks_checkpoint)
   218                  break;
   219          }
   220      }
   221
   222      /* Create the new sample point */
   223      for(size_t i = 0; i < wq->workersSize; ++i)
   224          wq->workers[i].checkpointCounter = wq->workers[i].counter;
   225      wq->delayedCallbacks_checkpoint = cb;
   226  }
   227
   228  #endif
