   248  /* Assumes all workers are shut down */
   249  void UA_WorkQueue_manuallyProcessDelayed(UA_WorkQueue *wq) {
   250      UA_DelayedCallback *dc, *dc_tmp;
   251      SIMPLEQ_FOREACH_SAFE(dc, &wq->delayedCallbacks, next, dc_tmp) {
   252          SIMPLEQ_REMOVE_HEAD(&wq->delayedCallbacks, next);
   253          if(dc->callback)
   254              dc->callback(dc->application, dc->data);
   255          UA_free(dc);
   256      }
   257  #ifdef UA_ENABLE_MULTITHREADING
   258      wq->delayedCallbacks_checkpoint = NULL;
   259  #endif
   260  }
