   140  /* The server needs to be stopped before it can be deleted */
   141  void UA_Server_delete(UA_Server *server) {
   142      /* Delete all internal data */
   143      UA_SecureChannelManager_deleteMembers(&server->secureChannelManager);
   144      UA_SessionManager_deleteMembers(&server->sessionManager);
   145      UA_Array_delete(server->namespaces, server->namespacesSize, &UA_TYPES[UA_TYPES_STRING]);
   146
   147  #ifdef UA_ENABLE_SUBSCRIPTIONS
   148      UA_MonitoredItem *mon, *mon_tmp;
   149      LIST_FOREACH_SAFE(mon, &server->localMonitoredItems, listEntry, mon_tmp) {
   150          LIST_REMOVE(mon, listEntry);
   151          UA_MonitoredItem_delete(server, mon);
   152      }
   153  #endif
   154
   155  #ifdef UA_ENABLE_PUBSUB
   156      UA_PubSubManager_delete(server, &server->pubSubManager);
   157  #endif
   158
   159  #ifdef UA_ENABLE_DISCOVERY
   160      registeredServer_list_entry *rs, *rs_tmp;
   161      LIST_FOREACH_SAFE(rs, &server->registeredServers, pointers, rs_tmp) {
   162          LIST_REMOVE(rs, pointers);
   163          UA_RegisteredServer_deleteMembers(&rs->registeredServer);
   164          UA_free(rs);
   165      }
   166      periodicServerRegisterCallback_entry *ps, *ps_tmp;
   167      LIST_FOREACH_SAFE(ps, &server->periodicServerRegisterCallbacks, pointers, ps_tmp) {
   168          LIST_REMOVE(ps, pointers);
   169          UA_free(ps->callback);
   170          UA_free(ps);
   171      }
   172
   173  # ifdef UA_ENABLE_DISCOVERY_MULTICAST
   174      if(server->config.applicationDescription.applicationType == UA_APPLICATIONTYPE_DISCOVERYSERVER)
   175          destroyMulticastDiscoveryServer(server);
   176
   177      serverOnNetwork_list_entry *son, *son_tmp;
   178      LIST_FOREACH_SAFE(son, &server->serverOnNetwork, pointers, son_tmp) {
   179          LIST_REMOVE(son, pointers);
   180          UA_ServerOnNetwork_deleteMembers(&son->serverOnNetwork);
   181          if(son->pathTmp)
   182              UA_free(son->pathTmp);
   183          UA_free(son);
   184      }
   185
   186      for(size_t i = 0; i < SERVER_ON_NETWORK_HASH_PRIME; i++) {
   187          serverOnNetwork_hash_entry* currHash = server->serverOnNetworkHash[i];
   188          while(currHash) {
   189              serverOnNetwork_hash_entry* nextHash = currHash->next;
   190              UA_free(currHash);
   191              currHash = nextHash;
   192          }
   193      }
   194
   195      mdnsHostnameToIp_list_entry *mhi, *mhi_tmp;
   196      LIST_FOREACH_SAFE(mhi, &server->mdnsHostnameToIp, pointers, mhi_tmp) {
   197          LIST_REMOVE(mhi, pointers);
   198          UA_String_deleteMembers(&mhi->mdnsHostname);
   199          UA_free(mhi);
   200      }
   201
   202      for(size_t i = 0; i < MDNS_HOSTNAME_TO_IP_HASH_PRIME; i++) {
   203          mdnsHostnameToIp_hash_entry* currHash = server->mdnsHostnameToIpHash[i];
   204          while(currHash) {
   205              mdnsHostnameToIp_hash_entry* nextHash = currHash->next;
   206              UA_free(currHash);
   207              currHash = nextHash;
   208          }
   209      }
   210  # endif
   211
   212  #endif
   213
   214      /* Clean up the Admin Session */
   215      UA_Session_deleteMembersCleanup(&server->adminSession, server);
   216
   217      /* Clean up the work queue */
   218      UA_WorkQueue_cleanup(&server->workQueue);
   219
   220      /* Delete the timed work */
   221      UA_Timer_deleteMembers(&server->timer);
   222
   223      /* Delete the server itself */
   224      UA_free(server);
   225  }
