   745  static UA_StatusCode
   746  processCompleteChunk(void *const application, UA_Connection *connection,
   747                       UA_ByteString *chunk) {
   748      UA_Server *server = (UA_Server*)application;
   749  #ifdef UA_DEBUG_DUMP_PKGS_FILE
   750      UA_debug_dumpCompleteChunk(server, connection, chunk);
   751  #endif
   752      if(!connection->channel)
   753          return processCompleteChunkWithoutChannel(server, connection, chunk);
   754      return UA_SecureChannel_decryptAddChunk(connection->channel, chunk, UA_FALSE);
   755  }
